8: import jwt from 'jsonwebtoken';
9: import { ConfigService } from '@nestjs/config';
10: import { AuthenticatedRequest } from '../utils/interface/interface.js';
11: 
12: @Injectable()
13: export class AuthGuard implements CanActivate {
14:   constructor(private readonly configService: ConfigService) {}
15: 
16:   canActivate(context: ExecutionContext): boolean {
17:     const req = context.switchToHttp().getRequest<AuthenticatedRequest>();
18: 
19:     // Authorization
20:     const authHeader = req.headers.authorization;
21: 
22:     if (!authHeader?.startsWith('Bearer ')) {
23:       throw new UnauthorizedException('Missing authentication token');
24:     }
25: 
26:     const token = authHeader.slice(7);
27: 
28:     try {
29:       const secret = this.configService.getOrThrow<string>('JWT_SECRET');
30: 
31:       const decoded = jwt.verify(token, secret);
32: 
33:       if (typeof decoded === 'string') {
34:         throw new UnauthorizedException('Invalid token payload');
35:       }
36: 
37:       // Attach decoded payload to request
38:       req.user = decoded;
39: 
40:       return true;
41:     } catch (error) {
42:       if (error instanceof UnauthorizedException) {
43:         throw error;
44:       }
45: 
46:       throw new UnauthorizedException('Invalid or expired token');
47:     }
48:   }
49: }

