private normalize(exception: unknown): NormalizedError {
  if (exception instanceof AppException) {
    return { status: exception.getStatus(), code: exception.code, message: exception.message, details: exception.details };
  }
  if (exception instanceof HttpException) {
    const status = exception.getStatus();
    const payload = exception.getResponse();
    if (typeof payload === 'string') return { status, code: this.defaultCode(status), message: payload };
    if (payload && typeof payload === 'object') {
      const record = payload as Record<string, unknown>;
      const rawMessage = record.message;
      const message = Array.isArray(rawMessage) ? 'Validation failed' : typeof rawMessage === 'string' ? rawMessage : exception.message;
      const details = Array.isArray(rawMessage) ? rawMessage.map((m) => ({ message: String(m) })) : undefined;
      const code = typeof record.code === 'string' ? record.code : status === 400 && details ? ErrorCode.VALIDATION_ERROR : this.defaultCode(status);
      return { status, code, message, details };
    }
    return { status, code: this.defaultCode(status), message: exception.message };
  }
  if (exception instanceof QueryFailedError) { ... }
  return { status: 500, code: ErrorCode.INTERNAL_SERVER_ERROR, message: 'An unexpected error occurred' };
}
```
