```ts
private fromQueryFailed(exception: QueryFailedError): NormalizedError {
  const driverError = exception.driverError as { code?: string; detail?: string; constraint?: string } | undefined;
  switch (driverError?.code) {
    case '23505': return { status:409, code:ErrorCode.DUPLICATE_RESOURCE, message:'A resource with the same unique value already exists' };
    case '23503': return { status:409, code:ErrorCode.FOREIGN_KEY_VIOLATION, message:'The operation violates a related resource constraint' };
    case '23502': return { status:400, code:ErrorCode.INVALID_INPUT, message:'A required field is missing' };
    case '22P02': return { status:400, code:ErrorCode.INVALID_INPUT, message:'One or more values have an invalid format' };
    case '23514': return { status:400, code:ErrorCode.INVALID_INPUT, message:'A value violates a database constraint' };
    default: return { status:500, code:ErrorCode.INTERNAL_SERVER_ERROR, message:'A database error occurred' };
  }
}
```
